    @EventHandler( payloadType=CreateSimCardEvent.class )
    public void handle( CreateSimCardEvent event) {
	    LOGGER.info("handling CreateSimCardEvent - " + event );
	    SimCard entity = new SimCard();
            entity.setSimCardId( event.getSimCardId() );
            entity.setIccid( event.getIccid() );
            entity.setImsi( event.getImsi() );
            entity.setCarrier( event.getCarrier() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSimCard( entity );
    }

