    /**
     * Method to retrieve the SimCard via an SimCardPrimaryKey.
     * @param 	id Long
     * @return 	SimCard
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public SimCard handle( FindSimCardQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getSimCardId() );
    }
    
    /**
     * Method to retrieve a collection of all SimCards
     *
     * @param	query	FindAllSimCardQuery 
     * @return 	List<SimCard> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<SimCard> handle( FindAllSimCardQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindSimCard,
 * but only if the id matches
 *
 * @param		entity	SimCard
 */
	protected void emitFindSimCard( SimCard entity ) {
		LOGGER.info("handling emitFindSimCard" );
		
	    queryUpdateEmitter.emit(FindSimCardQuery.class,
	                            query -> query.getFilter().getSimCardId().equals(entity.getSimCardId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllSimCard
	 * 
	 * @param		entity	SimCard
	 */
	protected void emitFindAllSimCard( SimCard entity ) {
		LOGGER.info("handling emitFindAllSimCard" );
		
	    queryUpdateEmitter.emit(FindAllSimCardQuery.class,
	                            query -> true,
	                            entity);
	}

